const area = async name => { await page.locator(`#rail [data-task="${name}"]`).evaluate(el => el.click()); await page.waitForTimeout(50); };
const harness = async (id, value) => { await page.locator(`#${id}`).selectOption(value); await page.waitForTimeout(60); };
const click = async sel => { await page.locator(sel).first().evaluate(el => { el.scrollIntoView({ block: 'center' }); el.click(); }); await page.waitForTimeout(40); };
/* a user-path click: playwright checks visibility, stability and that the point hits the element (recorded class UI-B) */
const pclick = async sel => { await page.locator(sel).first().click({ timeout: 3000 }); await page.waitForTimeout(40); };
const hit = sel => page.locator(sel).first().evaluate(el => { const r = el.getBoundingClientRect(); const e = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2); return !!e && (e === el || el.contains(e)); });
