const text = async sel => (await page.locator(sel).first().innerText()).replace(/\s+/g, ' ');
/* textContent joins panes that are hidden behind a tab; innerText would read '' for them */
const content = async (...sels) => (await page.evaluate(sels => sels.map(s => { const e = document.querySelector(s); if (!e) return ''; const w = document.createTreeWalker(e, NodeFilter.SHOW_TEXT); const parts = []; while (w.nextNode()) parts.push(w.currentNode.nodeValue); return parts.join(' '); }).join(' '), sels)).replace(/\s+/g, ' ');
const runText = () => content('#inspector', '#run-console', '#run-queue', '#run-log', '#project', '#status-msg');
const resText = () => content('#results-viewport', '#results-timeline', '#results-sweep', '#results-cand', '#layer-list', '#inspector', '#status-msg');
const measure = async label => {
  const row = await page.evaluate(() => ({ ...window.workbenchAudit, overflow: document.documentElement.scrollWidth > innerWidth }));
  assert(row.frame.width > 0 && row.frame.height > 0, `${label}: frame must render`);
  assert.equal(row.contrastFailures, 0, `${label}: token contrast`);
  assert.equal(row.smallTargets, 0, `${label}: targets under the 24 px floor`);
  assert.equal(row.denseUnder, 0, `${label}: dense controls under 32 px`);
  assert.equal(row.overflow, false, `${label}: horizontal page overflow`);
  /* the thick-client contract (UI-H2): the window never scrolls, the toolbar is one 44 px row that never overflows, every dock scrolls internally */
  assert.equal(row.shell.windowScroll, false, `${label}: the window must not scroll`);
  assert.equal(row.shell.toolbarOverflow, false, `${label}: the toolbar must not overflow its row`);
  assert(row.shell.toolbarRows <= 44, `${label}: toolbar height ${row.shell.toolbarRows} > 44`);
  assert.equal(row.shell.docksScrollInternally, true, `${label}: docks must scroll internally`);
  assert.equal(!!row.shell.statusOverflow, false, `${label}: the status bar must not clip`); assert.equal(!!row.shell.paramrowOverflow, false, `${label}: the parameter row must not clip`); assert.equal(!!row.shell.doctabsOverflow, false, `${label}: the document-tab row must not clip`);
  measurements.push({ label, frame: row.frame, controls: row.controls, contrastFailures: row.contrastFailures, smallTargets: row.smallTargets, shell: row.shell, theme: row.theme, state: row.state, task: row.task, window: row.window });
};
const smallestText = () => page.evaluate(() => { const out = []; for (const t of document.querySelectorAll('#window svg text')) { const svg = t.ownerSVGElement; const r = svg.getBoundingClientRect(); if (!r.width || !r.height || t.getBoundingClientRect().width === 0) continue; const vb = svg.viewBox.baseVal; const scale = vb && vb.width ? Math.min(r.width / vb.width, r.height / vb.height) : 1; out.push({ px: +(parseFloat(t.getAttribute('font-size') || getComputedStyle(t).fontSize) * scale).toFixed(1), text: t.textContent.slice(0, 40) }); } return out.sort((a, b) => a.px - b.px)[0] || { px: 99, text: '(no svg text)' }; });
const shellNumbers = () => page.evaluate(() => { const win = document.getElementById('window'); const tb = document.getElementById('toolbar'); const pr = document.getElementById('paramrow'); const more = document.getElementById('tb-more'); return { window: [win.clientWidth, win.clientHeight], scrollH: win.scrollHeight, scrollW: win.scrollWidth, toolbarH: Math.round(tb.getBoundingClientRect().height), toolbarOverflow: tb.scrollWidth > tb.clientWidth + 1, paramrowH: Math.round(pr.getBoundingClientRect().height), moreVisible: more ? getComputedStyle(more).display !== 'none' : false, hiddenGroups: document.querySelectorAll('#tb-menu .tb-group').length, rowGroups: document.querySelectorAll('#toolbar > .tb-group').length, docks: [...document.querySelectorAll('#window .dbody, #window .bpane, #window .docbody.scroll')].filter(e => e.offsetParent !== null).map(e => ({ id: e.id || e.className, overflowY: getComputedStyle(e).overflowY, scrolls: e.scrollHeight > e.clientHeight })) }; });
