    assert.equal(n.toolbarH, 44, `${w}/${a}: toolbar is one 44 px row`); assert.equal(n.toolbarOverflow, false, `${w}/${a}: toolbar overflow`); assert(n.paramrowH <= 44, `${w}/${a}: parameter row ${n.paramrowH} px is more than one row`);
